/**
 * Byte-level primitives shared by the hashing / encoding layers.
 *
 * Everything below operates on Uint8Array so that the JWS pipeline never has to
 * think about string encodings once a value has crossed into "bytes" territory,
 * mirroring the str -> bytes boundary the Python original relies on.
 */

/**
 * Encode a JS string to UTF-8 bytes.
 *
 * Lone surrogates (which Python can produce through the `surrogateescape`
 * error handler applied to argv) are emitted in WTF-8 form rather than being
 * replaced, so no information is lost if such a string ever reaches this
 * function. In practice the JSON layer escapes them first, keeping the signed
 * bytes pure ASCII.
 */
export function utf8Encode(str) {
  const out = [];
  for (let i = 0; i < str.length; i += 1) {
    let cp = str.charCodeAt(i);

    // Combine a well-formed surrogate pair into a single code point.
    if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < str.length) {
      const low = str.charCodeAt(i + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (low - 0xdc00);
        i += 1;
      }
    }

    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return new Uint8Array(out);
}

/** Number of bytes a UTF-8 continuation byte set implies for a lead byte, or 0 if invalid. */
function sequenceLength(lead) {
  if (lead < 0x80) return 1;
  if (lead >= 0xc2 && lead <= 0xdf) return 2;
  if (lead >= 0xe0 && lead <= 0xef) return 3;
  if (lead >= 0xf0 && lead <= 0xf4) return 4;
  return 0;
}

/**
 * Decode UTF-8 bytes the way CPython decodes `sys.argv`: valid sequences turn
 * into their code points, and every byte that cannot start or continue a valid
 * sequence becomes U+DC00+byte (the `surrogateescape` convention).
 */
export function utf8DecodeSurrogateEscape(bytes) {
  let out = '';
  let i = 0;

  while (i < bytes.length) {
    const lead = bytes[i];
    const need = sequenceLength(lead);

    if (need === 1) {
      out += String.fromCharCode(lead);
      i += 1;
      continue;
    }

    let cp = -1;
    if (need !== 0 && i + need <= bytes.length) {
      if (need === 2) {
        cp = lead & 0x1f;
      } else if (need === 3) {
        cp = lead & 0x0f;
      } else {
        cp = lead & 0x07;
      }
      for (let k = 1; k < need; k += 1) {
        const cont = bytes[i + k];
        if ((cont & 0xc0) !== 0x80) {
          cp = -1;
          break;
        }
        cp = (cp << 6) | (cont & 0x3f);
      }
      // Reject overlong forms, UTF-16 surrogates and out-of-range values.
      if (cp >= 0xd800 && cp <= 0xdfff) cp = -1;
      if (need === 3 && cp < 0x800) cp = -1;
      if (need === 4 && (cp < 0x10000 || cp > 0x10ffff)) cp = -1;
    }

    if (cp < 0) {
      out += String.fromCharCode(0xdc00 + lead);
      i += 1;
      continue;
    }

    out += String.fromCodePoint(cp);
    i += need;
  }

  return out;
}

/** Concatenate any number of byte arrays into one. */
export function concatBytes(...chunks) {
  let total = 0;
  for (const chunk of chunks) total += chunk.length;

  const out = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.length;
  }
  return out;
}

/** Coerce a string-or-bytes value into bytes, as Python's hmac module does with keys. */
export function toBytes(value) {
  if (value instanceof Uint8Array) return value;
  if (typeof value === 'string') return utf8Encode(value);
  throw new TypeError('expected str or bytes');
}

