const INITIAL_STATE = new Uint32Array([
  0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
]);

const BLOCK_SIZE = 64;
const DIGEST_SIZE = 32;

/** Rotate a 32-bit word right by n bits. */
function rotr(x, n) {
  return ((x >>> n) | (x << (32 - n))) >>> 0;
}

/**
 * Append the SHA-2 padding: a 0x80 byte, zeros, then the message length in
 * bits as a 64-bit big-endian integer.
 */
function padMessage(bytes) {
  const bitLength = bytes.length * 8;
  const paddedLength = ((bytes.length + 9 + 63) & ~63) >>> 0;

  const block = new Uint8Array(paddedLength);
  block.set(bytes);
  block[bytes.length] = 0x80;

  // Lengths above 2^53 bits are unreachable here, so a float split is safe.
  const high = Math.floor(bitLength / 0x100000000);
  const low = bitLength >>> 0;
  const tail = paddedLength - 8;
  block[tail] = (high >>> 24) & 0xff;
  block[tail + 1] = (high >>> 16) & 0xff;
  block[tail + 2] = (high >>> 8) & 0xff;
  block[tail + 3] = high & 0xff;
  block[tail + 4] = (low >>> 24) & 0xff;
  block[tail + 5] = (low >>> 16) & 0xff;
  block[tail + 6] = (low >>> 8) & 0xff;
  block[tail + 7] = low & 0xff;

  return block;
