/**
 * Keyed-hash message authentication (RFC 2104), written against the hash
 * descriptors from this package so no platform primitives are involved.
 */

import { concatBytes, toBytes } from './bytes.mjs';

/**
 * Normalise a key to exactly one hash block: longer keys are hashed down,
 * shorter keys are zero-padded on the right.
 */
function normaliseKey(keyBytes, hash) {
  const key = keyBytes.length > hash.blockSize ? hash.digest(keyBytes) : keyBytes;
  const block = new Uint8Array(hash.blockSize);
  block.set(key);
  return block;
}

/**
 * HMAC(key, message) using the given hash descriptor.
 *
 * @param {Uint8Array|string} key
 * @param {Uint8Array|string} message
 * @param {{blockSize: number, digest: (b: Uint8Array) => Uint8Array}} hash
 * @returns {Uint8Array} the raw MAC
 */
export function hmac(key, message, hash) {
  const block = normaliseKey(toBytes(key), hash);
  const messageBytes = toBytes(message);

  const innerPad = new Uint8Array(hash.blockSize);
  const outerPad = new Uint8Array(hash.blockSize);
  for (let i = 0; i < hash.blockSize; i += 1) {
    innerPad[i] = block[i] ^ 0x36;
    outerPad[i] = block[i] ^ 0x5c;
  }

  const inner = hash.digest(concatBytes(innerPad, messageBytes));
  return hash.digest(concatBytes(outerPad, inner));
}

