/**
 * base64url codec (RFC 4648 §5) with padding stripped, which is the form JOSE
 * uses for every compact-serialisation segment.
 */

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

/**
 * Encode bytes as unpadded base64url.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function base64urlEncode(bytes) {
  let out = '';

  let i = 0;
  for (; i + 2 < bytes.length; i += 3) {
    const triple = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2];
    out +=
      ALPHABET[(triple >>> 18) & 0x3f] +
      ALPHABET[(triple >>> 12) & 0x3f] +
      ALPHABET[(triple >>> 6) & 0x3f] +
      ALPHABET[triple & 0x3f];
  }

  const remaining = bytes.length - i;
