/**
 * A serialiser that reproduces CPython's `json.dumps` byte-for-byte for the
 * value shapes JOSE puts on the wire.
 *
 * The two behaviours that matter for signature compatibility are the
 * `ensure_ascii` escaping table (anything outside printable ASCII becomes a
 * `\uXXXX` escape with lowercase hex) and the caller-supplied separators.
 */

const SHORT_ESCAPES = {
  0x08: '\\b',
  0x09: '\\t',
  0x0a: '\\n',
  0x0c: '\\f',
  0x0d: '\\r',
  0x22: '\\"',
  0x5c: '\\\\',
};

/** Render a `\uXXXX` escape with lowercase hex digits, as CPython does. */
function unicodeEscape(code) {
  return `\\u${code.toString(16).padStart(4, '0')}`;
}

/**
 * Quote a string exactly like `json.encoder.encode_basestring_ascii`.
 *
 * Iteration is over UTF-16 code units on purpose: astral characters are stored
 * as surrogate pairs in JS strings, and CPython emits the same pair of escapes.
 * Lone surrogates (from `surrogateescape`-decoded argv) therefore survive as
 * plain `\udcXX` escapes instead of raising.
 */
export function encodeStringAscii(str) {
  let out = '"';

  for (let i = 0; i < str.length; i += 1) {
    const code = str.charCodeAt(i);
    const short = SHORT_ESCAPES[code];

    if (short !== undefined) {
      out += short;
    } else if (code < 0x20 || code > 0x7e) {
      out += unicodeEscape(code);
    } else {
      out += str[i];
    }
  }

  return `${out}"`;
}

/** Render a number the way CPython's JSON encoder does. */
function encodeNumber(value) {
  if (Number.isNaN(value)) return 'NaN';
  if (value === Infinity) return 'Infinity';
  if (value === -Infinity) return '-Infinity';
  return String(value);
}

/**
 * Serialise `value` to a JSON string.
 *
 * @param {unknown} value
 * @param {{separators?: [string, string], sortKeys?: boolean}} [options]
 *   `separators` is the `(item, key)` pair from Python; defaults to the
 *   `(', ', ': ')` Python uses when the argument is omitted.
 * @returns {string}
 */
export function dumps(value, options = {}) {
  const [itemSeparator, keySeparator] = options.separators ?? [', ', ': '];
  const sortKeys = options.sortKeys ?? false;

  const encode = (node) => {
    if (node === null || node === undefined) return 'null';
    if (typeof node === 'boolean') return node ? 'true' : 'false';
    if (typeof node === 'number') return encodeNumber(node);
    if (typeof node === 'string') return encodeStringAscii(node);

    if (Array.isArray(node)) {
      return `[${node.map(encode).join(itemSeparator)}]`;
    }

    if (typeof node === 'object') {
      const keys = Object.keys(node);
      // Python compares str keys by code point; JS default sort compares UTF-16
      // code units, which agrees for every key JOSE actually emits.
      if (sortKeys) keys.sort();
      const parts = keys.map((key) => `${encodeStringAscii(key)}${keySeparator}${encode(node[key])}`);
      return `{${parts.join(itemSeparator)}}`;
    }

    throw new TypeError(`Object of type ${typeof node} is not JSON serializable`);
  };

  return encode(value);
}

