/**
 * Registry of JWS signing algorithms.
 *
 * Only the HMAC family backed by the SHA-256 implementation in this package is
 * wired up, which covers the default `HS256` the Python original relies on.
 * Anything else fails the way python-jose does rather than silently degrading.
 */

import { hmac } from './hmac.mjs';
import { SHA256 } from './sha256.mjs';
import { JWSAlgorithmError } from './errors.mjs';

export const ALGORITHMS = {
  NONE: 'none',
  HS256: 'HS256',
  HS384: 'HS384',
  HS512: 'HS512',
};

/** Algorithms this implementation can actually produce signatures for. */
const SIGNERS = {
  [ALGORITHMS.HS256]: (key, signingInput) => hmac(key, signingInput, SHA256),
};

/** True when `algorithm` is a name JOSE recognises at all. */
export function isKnownAlgorithm(algorithm) {
  return Object.values(ALGORITHMS).includes(algorithm);
}

/**
 * Look up the signing function for `algorithm`.
 *
 * @param {string} algorithm
 * @returns {(key: Uint8Array|string, signingInput: Uint8Array) => Uint8Array}
 */
export function getSigner(algorithm) {
  if (!isKnownAlgorithm(algorithm)) {
    throw new JWSAlgorithmError(`Algorithm ${algorithm} not supported.`);
  }

  const signer = SIGNERS[algorithm];
  if (!signer) {
    throw new JWSAlgorithmError(`Algorithm ${algorithm} is not implemented.`);
  }
  return signer;
}

