/**
 * JWS compact serialisation: `base64url(header).base64url(payload).base64url(sig)`.
 *
 * Two details drive signature equality with python-jose:
 *   - the protected header is dumped with `sort_keys=True`, so `alg` precedes `typ`;
 *   - both header and payload use the compact `(',', ':')` separators.
 */

import { utf8Encode, concatBytes } from './bytes.mjs';
import { base64urlEncode } from './base64url.mjs';
import { dumps } from './pyjson.mjs';
import { ALGORITHMS, getSigner } from './algorithms.mjs';

const COMPACT_SEPARATORS = [',', ':'];

/** Build and encode the protected header segment. */
function encodeHeader(algorithm, additionalHeaders) {
  const header = { typ: 'JWT', alg: algorithm, ...(additionalHeaders ?? {}) };
  const json = dumps(header, { separators: COMPACT_SEPARATORS, sortKeys: true });
  return base64urlEncode(utf8Encode(json));
}

/** Encode the payload segment; raw bytes pass through untouched. */
function encodePayload(payload) {
  if (payload instanceof Uint8Array) {
    return base64urlEncode(payload);
  }
  const json = dumps(payload, { separators: COMPACT_SEPARATORS });
  return base64urlEncode(utf8Encode(json));
}

/**
 * Sign a payload and return the compact JWS.
 *
 * @param {object|Uint8Array} payload
 * @param {Uint8Array|string} key
 * @param {{headers?: object, algorithm?: string}} [options]
 * @returns {string}
 */
export function sign(payload, key, options = {}) {
  const algorithm = options.algorithm ?? ALGORITHMS.HS256;
  const signer = getSigner(algorithm);

  const signingInput = `${encodeHeader(algorithm, options.headers)}.${encodePayload(payload)}`;
  const signature = signer(key, utf8Encode(signingInput));

  return `${signingInput}.${base64urlEncode(signature)}`;
}

/** Exposed for callers that need the exact bytes that were authenticated. */
export function signingInputBytes(payload, options = {}) {
  const algorithm = options.algorithm ?? ALGORITHMS.HS256;
  const input = `${encodeHeader(algorithm, options.headers)}.${encodePayload(payload)}`;
  return concatBytes(utf8Encode(input));
}

