/**
 * The `jose.jwt` surface used by the migrated script.
 *
 * `jwt.encode` is a thin wrapper over the JWS layer: it validates the claim
 * container, normalises the registered time claims, then delegates to `jws.sign`.
 */

import { sign } from './jws.mjs';
import { ALGORITHMS } from './algorithms.mjs';
import { JWTError } from './errors.mjs';

const TIME_CLAIMS = ['exp', 'iat', 'nbf'];

/**
 * Normalise datetime-like time claims to integer POSIX timestamps, matching the
 * conversion python-jose applies before signing.
 */
function normaliseTimeClaims(claims) {
  const normalised = { ...claims };

  for (const claim of TIME_CLAIMS) {
    const value = normalised[claim];
    if (value instanceof Date) {
      normalised[claim] = Math.floor(value.getTime() / 1000);
    }
  }

  return normalised;
}

/**
 * Encode a claims object into a signed JWT.
 *
 * @param {object} claims claim set to sign
 * @param {Uint8Array|string} key signing key
 * @param {string} [algorithm] defaults to HS256, as in python-jose
 * @param {object} [headers] extra protected-header members
 * @returns {string} the compact JWT
 */
export function encode(claims, key, algorithm = ALGORITHMS.HS256, headers = undefined) {
  if (claims === null || typeof claims !== 'object' || Array.isArray(claims)) {
    throw new JWTError('Claims must be a dict.');
  }

  return sign(normaliseTimeClaims(claims), key, { headers, algorithm });
}

export const jwt = { encode };
export default jwt;

