/**
 * Raw command-line access.
 *
 * `process.argv` has already been lossily decoded as UTF-8 by V8, so bytes that
 * are not valid UTF-8 arrive as U+FFFD. CPython instead decodes argv with the
 * `surrogateescape` error handler, turning each undecodable byte into
 * U+DC00+byte. Reading `/proc/self/cmdline` gets us the original bytes back so
 * the two runtimes agree even on non-UTF-8 input.
 */

import { readFileSync } from 'node:fs';
import { utf8DecodeSurrogateEscape } from './bytes.mjs';

/** Split a NUL-delimited cmdline buffer into its individual arguments. */
function splitNulDelimited(buffer) {
  const parts = [];
  let start = 0;

  for (let i = 0; i < buffer.length; i += 1) {
    if (buffer[i] === 0) {
      parts.push(buffer.subarray(start, i));
      start = i + 1;
    }
  }
  if (start < buffer.length) parts.push(buffer.subarray(start));

  return parts;
}

/**
 * The user-supplied arguments, i.e. the equivalent of `sys.argv[1:]`.
 *
 * Falls back to `process.argv.slice(2)` on platforms without procfs, or if the
 * cmdline contents do not line up with what the runtime reports.
 */
export function userArguments() {
  const expected = process.argv.length - 2;
  if (expected <= 0) return [];

  try {
    const parts = splitNulDelimited(readFileSync('/proc/self/cmdline'));
    if (parts.length < expected) return process.argv.slice(2);

    return parts
      .slice(parts.length - expected)
      .map((part) => utf8DecodeSurrogateEscape(new Uint8Array(part)));
  } catch {
    return process.argv.slice(2);
  }
}

