/**
 * A faithful subset of CPython's `argparse`, covering optional arguments with
 * `store` and `help` actions.
 *
 * Reproduced behaviours that a naive parser gets wrong:
 *   - long-option prefix abbreviation (`--pay` resolves to `--payload`);
 *   - `--opt=value` as well as `--opt value`;
 *   - option-like values are refused (`--payload -abc` is an error) while
 *     negative numbers are accepted (`--payload -5` is not);
 *   - only the first `--` terminates option parsing, and it is itself reported
 *     as an unrecognised argument when there are no positionals to absorb it;
 *   - missing-required is reported before unrecognised-arguments;
 *   - exact usage/help layout, and exit status 2 on error.
 */

import { HelpFormatter } from './argparse_format.mjs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Default `prog`: what argparse derives from `sys.argv[0]`. */
function defaultProg() {
  const script = process.argv[1] ?? '';
  const basename = script.split('/').pop();
  return basename || 'program';
}

class Action {
  constructor({ optionStrings, dest, kind, required, metavar, help, type }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.kind = kind; // 'store' | 'help'
    this.required = required;
    this.metavar = metavar;
    this.help = help;
    this.type = type;
  }

  /** Number of following tokens consumed; `null` means exactly one. */
  get nargs() {
    return this.kind === 'help' ? 0 : null;
  }
}

export class ArgumentParser {
  /**
   * @param {{prog?: string, addHelp?: boolean}} [options]
   */
  constructor(options = {}) {
    this.prog = options.prog ?? defaultProg();
    this._actions = [];
    this._optionStringActions = new Map();

    if (options.addHelp ?? true) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
