/**
 * Usage/help rendering that reproduces `argparse.HelpFormatter` layout
 * exactly — column positions, the two-space gutter, the blank line between the
 * usage line and the `options:` section, and the trailing-newline handling.
 */

/**
 * Terminal width as argparse sees it: `COLUMNS` if set, otherwise the 80-column
 * fallback `shutil.get_terminal_size` uses when stdout is not a terminal.
 */
function terminalWidth() {
  const columns = Number.parseInt(process.env.COLUMNS ?? '', 10);
  return Number.isFinite(columns) && columns > 0 ? columns : 80;
}

/** Greedy wrap, matching `textwrap.wrap` for the single-space text argparse passes it. */
function wrapText(text, width) {
  const words = text.split(/\s+/).filter(Boolean);
  const lines = [];
  let line = '';

  for (const word of words) {
    if (line === '') {
      line = word;
    } else if (line.length + 1 + word.length <= width) {
      line += ` ${word}`;
    } else {
      lines.push(line);
      line = word;
    }
  }
  if (line !== '') lines.push(line);

  return lines.length ? lines : [''];
}

export class HelpFormatter {
  /**
   * @param {string} prog program name shown in the usage line
   * @param {Array<object>} actions registered actions, in declaration order
   */
  constructor(prog, actions) {
    this.prog = prog;
    this.actions = actions;
    this.indent = 2;
    this.maxHelpPosition = 24;
    this.width = terminalWidth() - 2;
  }

  /** `--payload PAYLOAD`, or `-h` — how an action appears in the usage line. */
  _usagePart(action) {
    const flag = action.optionStrings[0];
    const body = action.nargs === 0 ? flag : `${flag} ${action.metavar}`;
    return action.required ? body : `[${body}]`;
  }

  /** `-h, --help` / `--payload PAYLOAD` — how an action appears in the options list. */
  _invocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return action.optionStrings.map((flag) => `${flag} ${action.metavar}`).join(', ');
  }

  /** Column at which help text starts. */
  _helpPosition() {
    let maxLength = 0;
    for (const action of this.actions) {
      maxLength = Math.max(maxLength, this._invocation(action).length + this.indent);
    }
    return Math.min(maxLength + 2, this.maxHelpPosition);
  }

  /**
   * Break `[prog, ...parts]` into usage lines, mirroring argparse's inner
   * `get_lines` helper.
   */
  _wrapUsage(parts, indent, prefix) {
    const textWidth = this.width;
    const lines = [];
    let line = [];
    let lineLength = (prefix === undefined ? indent.length : prefix.length) - 1;

    for (const part of parts) {
      if (lineLength + 1 + part.length > textWidth && line.length) {
        lines.push(indent + line.join(' '));
        line = [];
        lineLength = indent.length - 1;
      }
      line.push(part);
      lineLength += 1 + part.length;
    }
    if (line.length) lines.push(indent + line.join(' '));
    if (prefix !== undefined && lines.length) lines[0] = lines[0].slice(indent.length);

    return lines;
  }

  /** The `usage: ...` block, terminated by a single newline. */
  formatUsage() {
    const prefix = 'usage: ';
    const parts = this.actions.map((action) => this._usagePart(action));
    let usage = [this.prog, parts.join(' ')].filter((piece) => piece !== '').join(' ');

    if (prefix.length + usage.length > this.width) {
      const indent = ' '.repeat(prefix.length + this.prog.length + 1);
      if (prefix.length + this.prog.length <= 0.75 * this.width) {
        usage = this._wrapUsage([this.prog, ...parts], indent, prefix).join('\n');
      } else {
        usage = this._wrapUsage(parts, ' '.repeat(prefix.length)).join('\n');
        usage = `${this.prog}\n${usage}`;
      }
    }

    return `${prefix}${usage}\n`;
  }

  /** One entry of the `options:` list, including its trailing newline. */
  _formatAction(action) {
    const invocation = this._invocation(action);
    const pad = ' '.repeat(this.indent);

    // No help text: the invocation stands alone on its line.
    if (!action.help || !action.help.trim()) {
      return `${pad}${invocation}\n`;
    }

    const helpPosition = this._helpPosition();
    const actionWidth = helpPosition - this.indent - 2;
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const helpLines = wrapText(action.help, helpWidth);

    let out;
    if (invocation.length <= actionWidth) {
      out = `${pad}${invocation.padEnd(actionWidth)}  ${helpLines[0]}\n`;
    } else {
      out = `${pad}${invocation}\n${' '.repeat(helpPosition)}${helpLines[0]}\n`;
    }
    for (const extra of helpLines.slice(1)) {
      out += `${' '.repeat(helpPosition)}${extra}\n`;
    }
    return out;
  }

  /** The complete `--help` output. */
  formatHelp() {
    let help = this.formatUsage();
    help += '\n';
    help += 'options:\n';
    for (const action of this.actions) help += this._formatAction(action);

    // argparse collapses runs of blank lines and normalises the trailing newline.
    return `${help.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
  }
}

